 import XCTest

 final class UITests: XCTestCase {
-    func testInspectRoom() {
+    func testInspectRoomDetails() {
         let app = XCUIApplication(bundleIdentifier: "im.vector.app")
         app.activate()
         XCTAssertTrue(app.staticTexts["Team Standup"].waitForExistence(timeout: 10))
-        let buttonInfo = app.buttons.allElementsBoundByIndex.map {
-            "label=\($0.label) identifier=\($0.identifier)"
