         let attachment = XCTAttachment(string: "BUTTONS\n\(buttonInfo)\n\nTREE\n\(app.debugDescription)")
-        attachment.name = "room-accessibility"
+        attachment.name = "room-details-accessibility"
         attachment.lifetime = .keepAlways
         add(attachment)
     }
 }

